class TenantGate
  def initialize(app, policy)
    @app, @policy = app, policy
  end
  def call(env)
    id = authenticate(env)                       # this gate's own evidence
    return [403, {"content-type" => "text/plain"}, ["forbidden"]] unless
      id && @policy.allows?(id, env)             # fail closed, short-circuit
    env["app.identity"] = id                     # hand identity inward
    @app.call(env)                               # delegate to the inner gate
  end
end
use TenantGate, TenantPolicy.new                 # Rack builds the nested chain
